import dearpygui.dearpygui as dpg

_DATA = json.loads(r"""{"square": {"color": {"bg": "#0a0a0a", "bgAlt": "#000000", "surface": "#101010", "surfaceAlt": "#151515", "fgStrong": "#ffffff", "fg": "#e2e2e2", "fgDim": "#b4b4b4", "fgMuted": "#919191", "fgFaint": "#787878", "lineSoft": "#202020", "line": "#3a3a3a", "lineStrong": "#656565", "focus": "#e2e2e2", "tint": "#151515", "accent": "#e2e2e2", "accentHover": "#b4b4b4", "onAccent": "#0a0a0a", "selection": "#313131", "onSelection": "#ffffff", "disabled": "#555555", "shadow": "#0a0a0a"}, "font": {"display": "Fraunces", "sans": "Space Grotesk", "strong": "Space Grotesk", "mono": "Space Mono"}, "fontFile": {"display": "Fraunces-Light.ttf", "sans": "SpaceGrotesk-Regular.ttf", "strong": "SpaceGrotesk-Medium.ttf", "mono": "SpaceMono-Regular.ttf"}, "weight": {"display": 300, "sans": 400, "strong": 500, "mono": 400}, "size": {"label": 11, "small": 12, "ui": 14, "body": 16, "h3": 20, "h2": 48, "h1": 96, "stat": 34}, "radius": {"sm": 0, "md": 0, "lg": 0, "pill": 0}, "border": {"width": 1, "focus": 1}, "control": {"height": 40, "heightSmall": 32, "padX": 18}, "label": {"uppercase": true, "tracking": 0.22, "weight": 500}, "light": false, "appPx": 15, "displayScale": 2.4}, "round": {"color": {"bg": "#131313", "bgAlt": "#0a0a0a", "surface": "#1f1f1f", "surfaceAlt": "#2a2a2a", "fgStrong": "#ffffff", "fg": "#e2e2e2", "fgDim": "#c6c6c6", "fgMuted": "#999999", "fgFaint": "#777777", "lineSoft": "#2a2a2a", "line": "#333333", "lineStrong": "#919191", "focus": "#999999", "tint": "#212121", "accent": "#ffffff", "accentHover": "#c6c6c6", "onAccent": "#1b1b1b", "selection": "#3a3a3a", "onSelection": "#ffffff", "disabled": "#777777", "shadow": "#0b0b0b"}, "font": {"display": "3270 Nerd Font", "sans": "3270 Nerd Font", "strong": "3270 Nerd Font", "mono": "3270 Nerd Font Mono"}, "fontFile": {"display": "3270NerdFont-Regular.ttf", "sans": "3270NerdFont-Regular.ttf", "strong": "3270NerdFont-Regular.ttf", "mono": "3270NerdFontMono-Regular.ttf"}, "weight": {"display": 400, "sans": 400, "strong": 700, "mono": 400}, "size": {"label": 11, "small": 12, "ui": 14, "body": 15, "h3": 18, "h2": 30, "h1": 56, "stat": 30}, "radius": {"sm": 6, "md": 8, "lg": 12, "pill": 999}, "border": {"width": 1, "focus": 2}, "control": {"height": 30, "heightSmall": 22, "padX": 12}, "label": {"uppercase": false, "tracking": 0.04, "weight": 700}, "light": false, "appPx": 16, "displayScale": 1.9}, "blend": {"color": {"bg": "#131313", "bgAlt": "#0a0a0a", "surface": "#1f1f1f", "surfaceAlt": "#2a2a2a", "fgStrong": "#ffffff", "fg": "#e2e2e2", "fgDim": "#c6c6c6", "fgMuted": "#919191", "fgFaint": "#777777", "lineSoft": "#242424", "line": "#343434", "lineStrong": "#5e5e5e", "focus": "#e2e2e2", "tint": "#1f1f1f", "accent": "#ffffff", "accentHover": "#c6c6c6", "onAccent": "#131313", "selection": "#383838", "onSelection": "#ffffff", "disabled": "#555555", "shadow": "#0c0c0c"}, "font": {"display": "Fraunces", "sans": "Space Grotesk", "strong": "Space Grotesk", "mono": "3270 Nerd Font Mono"}, "fontFile": {"display": "Fraunces-Light.ttf", "sans": "SpaceGrotesk-Regular.ttf", "strong": "SpaceGrotesk-Medium.ttf", "mono": "3270NerdFontMono-Regular.ttf"}, "weight": {"display": 300, "sans": 400, "strong": 500, "mono": 400}, "size": {"label": 11, "small": 12, "ui": 14, "body": 15, "h3": 19, "h2": 38, "h1": 72, "stat": 32}, "radius": {"sm": 4, "md": 6, "lg": 10, "pill": 999}, "border": {"width": 1, "focus": 1}, "control": {"height": 34, "heightSmall": 26, "padX": 14}, "label": {"uppercase": true, "tracking": 0.12, "weight": 500}, "light": false, "appPx": 15, "displayScale": 2.4}, "paper": {"color": {"bg": "#f2f2f2", "bgAlt": "#ffffff", "surface": "#e9e9e9", "surfaceAlt": "#e4e4e4", "fgStrong": "#000000", "fg": "#111111", "fgDim": "#333333", "fgMuted": "#5c5c5c", "fgFaint": "#858585", "lineSoft": "#dcdcdc", "line": "#bcbcbc", "lineStrong": "#868686", "focus": "#111111", "tint": "#e7e7e7", "accent": "#111111", "accentHover": "#3a3a3a", "onAccent": "#f2f2f2", "selection": "#d2d2d2", "onSelection": "#000000", "disabled": "#a3a3a3", "shadow": "#f2f2f2"}, "font": {"display": "Fraunces", "sans": "Space Grotesk", "strong": "Space Grotesk", "mono": "Space Mono"}, "fontFile": {"display": "Fraunces-Light.ttf", "sans": "SpaceGrotesk-Regular.ttf", "strong": "SpaceGrotesk-Medium.ttf", "mono": "SpaceMono-Regular.ttf"}, "weight": {"display": 300, "sans": 400, "strong": 500, "mono": 400}, "size": {"label": 11, "small": 12, "ui": 14, "body": 16, "h3": 20, "h2": 48, "h1": 96, "stat": 34}, "radius": {"sm": 0, "md": 0, "lg": 0, "pill": 0}, "border": {"width": 1, "focus": 1}, "control": {"height": 40, "heightSmall": 32, "padX": 18}, "label": {"uppercase": true, "tracking": 0.22, "weight": 500}, "light": true, "appPx": 15, "displayScale": 2.4}}""")


def _rgba(hexv: str, a: int = 255):
    h = hexv.lstrip("#")
    return (int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16), a)


def _font_dir():
    env = os.environ.get("MONO_UI_FONTS")
    if env:
        return Path(env)
    for up in Path(__file__).resolve().parents:
        if (up / "fonts" / "ttf").is_dir():
            return up / "fonts" / "ttf"
    return None


def apply(variant: str = "round", font_px: int | None = None) -> dict:
    """Create and bind the mono theme. Returns {"global", "fill", "line", "ghost", "muted", "fonts": {...}}."""
    d = _DATA[variant]
    c, r = d["color"], d["radius"]
    C = lambda k, a=255: _rgba(c[k], a)
    out = {}
    with dpg.theme() as g:
        with dpg.theme_component(dpg.mvAll):
            for col, val in [
                (dpg.mvThemeCol_Text, C("fg")), (dpg.mvThemeCol_TextDisabled, C("disabled")),
                (dpg.mvThemeCol_WindowBg, C("bg")), (dpg.mvThemeCol_ChildBg, C("bg")), (dpg.mvThemeCol_PopupBg, C("surface")),
                (dpg.mvThemeCol_Border, C("line")), (dpg.mvThemeCol_BorderShadow, (0, 0, 0, 0)),
                (dpg.mvThemeCol_FrameBg, C("bgAlt")), (dpg.mvThemeCol_FrameBgHovered, C("surface")),
                (dpg.mvThemeCol_FrameBgActive, C("surfaceAlt")), (dpg.mvThemeCol_TitleBg, C("bgAlt")),
                (dpg.mvThemeCol_TitleBgActive, C("surface")), (dpg.mvThemeCol_MenuBarBg, C("bgAlt")),
                (dpg.mvThemeCol_ScrollbarBg, (0, 0, 0, 0)), (dpg.mvThemeCol_ScrollbarGrab, C("lineStrong")),
                (dpg.mvThemeCol_ScrollbarGrabHovered, C("fgMuted")), (dpg.mvThemeCol_ScrollbarGrabActive, C("fg")),
                (dpg.mvThemeCol_CheckMark, C("fgStrong")), (dpg.mvThemeCol_SliderGrab, C("fg")),
                (dpg.mvThemeCol_SliderGrabActive, C("fgStrong")), (dpg.mvThemeCol_Button, (0, 0, 0, 0)),
                (dpg.mvThemeCol_ButtonHovered, C("surface")), (dpg.mvThemeCol_ButtonActive, C("surfaceAlt")),
                (dpg.mvThemeCol_Header, C("selection")), (dpg.mvThemeCol_HeaderHovered, C("surfaceAlt")),
                (dpg.mvThemeCol_HeaderActive, C("selection")), (dpg.mvThemeCol_Separator, C("line")),
                (dpg.mvThemeCol_Tab, (0, 0, 0, 0)), (dpg.mvThemeCol_TabHovered, C("surfaceAlt")),
                (dpg.mvThemeCol_TabActive, C("surface")), (dpg.mvThemeCol_PlotLines, C("fgDim")),
                (dpg.mvThemeCol_PlotHistogram, C("fgDim")), (dpg.mvThemeCol_TableHeaderBg, C("bgAlt")),
                (dpg.mvThemeCol_TableBorderStrong, C("line")), (dpg.mvThemeCol_TableBorderLight, C("lineSoft")),
                (dpg.mvThemeCol_TableRowBgAlt, C("surface", 90)), (dpg.mvThemeCol_TextSelectedBg, C("selection")),
                (dpg.mvThemeCol_ModalWindowDimBg, (0, 0, 0, 110)),
            ]:
                dpg.add_theme_color(col, val, category=dpg.mvThemeCat_Core)
            sq = r["md"] == 0  # square corners
            for var, val in [
                (dpg.mvStyleVar_WindowRounding, r["lg"]), (dpg.mvStyleVar_ChildRounding, r["md"]),
                (dpg.mvStyleVar_FrameRounding, r["md"]), (dpg.mvStyleVar_PopupRounding, r["md"]),
                (dpg.mvStyleVar_GrabRounding, 0 if sq else 7), (dpg.mvStyleVar_TabRounding, r["md"]),
                (dpg.mvStyleVar_ScrollbarRounding, 0 if sq else 4), (dpg.mvStyleVar_FrameBorderSize, 1),
                (dpg.mvStyleVar_WindowBorderSize, 1), (dpg.mvStyleVar_ChildBorderSize, 1), (dpg.mvStyleVar_PopupBorderSize, 1),
                (dpg.mvStyleVar_ScrollbarSize, 10), (dpg.mvStyleVar_GrabMinSize, 12),
            ]:
                dpg.add_theme_style(var, val, category=dpg.mvThemeCat_Core)
            dpg.add_theme_style(dpg.mvStyleVar_FramePadding, d["control"]["padX"], 6 if sq else 4, category=dpg.mvThemeCat_Core)
            dpg.add_theme_style(dpg.mvStyleVar_ItemSpacing, 10, 8, category=dpg.mvThemeCat_Core)
            dpg.add_theme_style(dpg.mvStyleVar_WindowPadding, 16, 14, category=dpg.mvThemeCat_Core)
    out["global"] = g

    def button_theme(**cols):
        with dpg.theme() as th:
            with dpg.theme_component(dpg.mvButton):
                for k, val in cols.items():
                    dpg.add_theme_color(getattr(dpg, f"mvThemeCol_{k}"), val, category=dpg.mvThemeCat_Core)
        return th

    out["fill"] = button_theme(Button=C("accent"), ButtonHovered=C("accentHover"), ButtonActive=C("fgMuted"),
                               Text=C("onAccent"), Border=C("accent"))
    out["line"] = button_theme(Border=C("lineStrong"))
    out["ghost"] = button_theme(Border=(0, 0, 0, 0), Text=C("fgMuted"))
    with dpg.theme() as muted:
        with dpg.theme_component(dpg.mvAll):
            dpg.add_theme_color(dpg.mvThemeCol_Text, C("fgMuted"), category=dpg.mvThemeCat_Core)
    out["muted"] = muted
    with dpg.theme() as faint:
        with dpg.theme_component(dpg.mvAll):
            dpg.add_theme_color(dpg.mvThemeCol_Text, C("fgFaint"), category=dpg.mvThemeCat_Core)
    out["faint"] = faint

    fonts = {}
    fd = _font_dir()
    px = font_px or d["appPx"]
    if fd:
        with dpg.font_registry():
            for role, scale in (("sans", 1.0), ("strong", 1.0), ("mono", 1.0), ("display", d["displayScale"])):
                path = fd / d["fontFile"][role]
                if path.exists():
                    fonts[role] = dpg.add_font(str(path), round(px * scale))
        if "sans" in fonts:
            dpg.bind_font(fonts["sans"])
    out["fonts"] = fonts
    dpg.bind_theme(g)
    return out
